require_once __DIR__.'/../../auth/auth_check.php';require_once __DIR__.'/../../config/database.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama_perusahaan']??'');$nomor=trim($_POST['nomor_kegiatan']??'');if($nama&&$nomor){$st=$pdo->prepare('INSERT INTO tarlam (nomor_kegiatan,nama_perusahaan,lokasi,luas_area,jenis_kegiatan,tahun_kegiatan,status,keterangan) VALUES (?,?,?,?,?,?,?,?)');$st->execute([$nomor,$nama,$_POST['lokasi']??'',(float)($_POST['luas_area']??0),$_POST['jenis_kegiatan']??'',(int)($_POST['tahun_kegiatan']??date('Y')),$_POST['status']??'Diajukan',$_POST['keterangan']??'']);header('Location: index.php');exit;}else{$error='Nomor kegiatan dan nama perusahaan wajib diisi.';}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tarlam | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Kegiatan Penggunaan Lahan</p><h1>Tarlam</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah Kegiatan</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" class="vstack gap-2"><input class="form-control" name="nomor_kegiatan" placeholder="Nomor kegiatan" required><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><input class="form-control" name="lokasi" placeholder="Lokasi"><input type="number" step="0.01" class="form-control" name="luas_area" placeholder="Luas area (Ha)"><input class="form-control" name="jenis_kegiatan" placeholder="Jenis kegiatan"><input type="number" class="form-control" name="tahun_kegiatan" value="<?=date('Y')?>"><select class="form-select" name="status"><option>Diajukan</option><option>Berjalan</option><option>Selesai</option></select><textarea class="form-control" name="keterangan" rows="2" placeholder="Keterangan"></textarea><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nomor</th><th>Perusahaan</th><th>Lokasi</th><th>Luas</th><th>Tahun</th><th>Status</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT * FROM tarlam ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_kegiatan'])?></td><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['lokasi'])?></td><td><?=number_format((float)$r['luas_area'],2)?> Ha</td><td><?=htmlspecialchars($r['tahun_kegiatan'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada data.</td></tr><?php endif?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
